<script setup>
import japaneseGlyphs from '../editor/sfx-glyphs.json';
import {computed} from 'vue';import {starPoints,stickerPresets} from '../editor/decorations';
const p=defineProps({id:String,color:{default:'#242633'},image:String});
const preset=computed(()=>stickerPresets.find(s=>s.id===p.id));const name=computed(()=>preset.value?.name||'✦');const glyph=computed(()=>japaneseGlyphs[preset.value?.glyphKey||p.id]);
const line=(x1,y1,x2,y2)=>`M${x1} ${y1}L${x2} ${y2}`;
const paths=computed(()=>{const id=p.id;if(['speed','speed-diagonal','rain','gloom','blush','tremble'].includes(id))return Array.from({length:id==='blush'?5:12},(_,i)=>{const v=8+i*7.5;if(id==='blush')return line(20+i*12,30,8+i*12,68);if(id==='rain')return line(v,5,v-20,95);if(id==='gloom')return line(v,8,v,25+(i%3)*15);if(id==='tremble')return `M${v} 12q-8 9 0 18t0 18t0 18t0 18`;return line(4,v,id==='speed-diagonal'?94:68+(i%4)*8,id==='speed-diagonal'?v-30:v);});if(['focus','focus-dense','rays','attention'].includes(id)){const n=id==='focus-dense'?48:id==='attention'?5:24;return Array.from({length:n},(_,i)=>{const a=(id==='attention'?-.9+i*.45:i*Math.PI*2/n),r=id==='attention'?22:26+(i%4)*3;return line(50+Math.cos(a)*r,50+Math.sin(a)*r,50+Math.cos(a)*48,50+Math.sin(a)*48);});}if(id==='spiral')return [Array.from({length:120},(_,i)=>{const a=i*.22,r=i*.33;return `${i?'L':'M'}${50+Math.cos(a)*r} ${50+Math.sin(a)*r}`;}).join(' ')];if(id==='wave'||id==='wind')return Array.from({length:4},(_,i)=>`M5 ${20+i*17} Q25 ${i*17} 50 ${20+i*17} T95 ${20+i*17}`);return [];});
</script>
<template><svg :preserveAspectRatio="image?'none':'xMidYMid meet'" viewBox="0 0 100 100" overflow="visible" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><image v-if="image" :href="image" width="100" height="100" preserveAspectRatio="none"/><g v-else :fill="color" :stroke="color" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
 <path v-if="glyph" :d="glyph" :fill="preset?.style==='outline'?'white':color" :stroke="preset?.style==='outline'?color:'white'" :stroke-width="preset?.style==='outline'?1.8:3" paint-order="stroke fill" :transform="preset?.style==='vertical'?undefined:'rotate(-10 50 50)'"/><template v-else-if="['heart','broken-heart','heart-outline','double-heart','heart-sparkle','heart-arrow','tiny-hearts'].includes(id)"><path d="M50 88C-12 50 3 6 32 17Q45 20 50 31Q65 5 85 20C117 48 70 78 50 88Z" :fill="id==='heart-outline'?'none':color" :stroke="color" stroke-width="4" :transform="['double-heart','tiny-hearts'].includes(id)?'translate(6 22) scale(.72)':undefined"/><path v-if="id==='double-heart'||id==='tiny-hearts'" d="M60 35C30 13 52 -3 61 11C75 -3 97 15 60 35Z"/><path v-if="id==='heart-arrow'" d="M6 90L90 8M76 9L93 6L92 24" fill="none" stroke-width="5"/><polygon v-if="id==='heart-sparkle'" :points="starPoints(4,16,4,78,18)" stroke="white" stroke-width="2"/><path v-if="id==='broken-heart'" d="M55 15L44 40L59 49L44 67L50 90" fill="none" stroke="white" stroke-width="5"/></template>
 <template v-else-if="['sweat','double-sweat','tear'].includes(id)"><path d="M55 7C51 30 19 47 25 68C33 101 80 94 80 65C80 47 67 22 55 7Z" :fill="id==='tear'?'none':color"/><path v-if="id==='double-sweat'" d="M20 8C18 20 4 29 5 39C8 54 28 52 30 39C31 28 25 17 20 8Z"/></template>
 <path v-else-if="id==='anger'" d="M14 20Q42 22 40 43M59 14Q56 41 77 40M86 65Q59 60 60 84M38 86Q42 59 15 59" fill="none" stroke-width="8"/>
 <template v-else-if="['star','stars','sparkle','sparkles','burst','impact'].includes(id)"><polygon :points="starPoints(id==='burst'?16:id==='impact'?7:id.startsWith('sparkle')?4:5,44,id==='burst'?29:id.startsWith('sparkle')?9:20)"/><polygon v-if="id==='stars'||id==='sparkles'" :points="starPoints(4,13,4,92,12)"/><polygon v-if="id==='stars'||id==='sparkles'" :points="starPoints(4,10,3,8,85)"/></template>
 <path v-else-if="id==='cloud'||id==='puff'" d="M18 74C-3 68 2 45 19 44C9 23 36 12 48 27C63 7 86 24 80 41C104 43 105 68 85 75Z"/>
 <ellipse v-else-if="id==='circle'" cx="50" cy="50" rx="44" ry="35" fill="none" stroke-width="5" transform="rotate(-12 50 50)"/>
 <path v-else-if="id==='cross'" d="M22 22L78 78M78 22L22 78" fill="none" stroke-width="12"/>
 <g v-else-if="paths.length" fill="none"><path v-for="(d,i) in paths" :d="d" :stroke-width="id==='focus-dense'?1:2+(i%3)*.5"/></g>
 <text v-else x="50" y="54" text-anchor="middle" dominant-baseline="middle" :font-size="id?.startsWith('sfx-')?id==='sfx-haha'?27:34:55" stroke="none" font-weight="900" font-family="Microsoft YaHei, Segoe UI Symbol, sans-serif">{{{sleep:'Zzz',question:'?',exclamation:'!',surprise:'!?',ellipsis:'…',music:'♪','double-music':'♫'}[id]||name}}</text>
 </g></svg></template>
